      "content": "<h3>All TreeSet methods at a glance</h3>\n<p><em>n</em> is the number of elements.</p>\n<table border=\"1\" cellpadding=\"8\" cellspacing=\"0\" style=\"border-collapse:collapse; width:100%;\">\n<tr><th style=\"text-align:left;\">Method</th><th style=\"text-align:left;\">What it does</th><th style=\"text-align:left;\">Time</th></tr>\n<tr><td><strong>add(e)</strong> / <strong>addAll(c)</strong></td><td>Adds in sorted position</td><td>O(log n)</td></tr>\n<tr><td><strong>remove(o)</strong> / <strong>removeIf(p)</strong> / <strong>clear()</strong></td><td>Removes elements</td><td>O(log n) / O(n)</td></tr>\n<tr><td><strong>contains(o)</strong> / <strong>size()</strong> / <strong>isEmpty()</strong></td><td>Lookup / count</td><td>O(log n) / O(1)</td></tr>\n<tr><td><strong>first()</strong> / <strong>last()</strong></td><td>Smallest / largest element (throws if empty)</td><td>O(log n)</td></tr>\n<tr><td><strong>pollFirst()</strong> / <strong>pollLast()</strong></td><td>Remove and return smallest / largest (null if empty)</td><td>O(log n)</td></tr>\n<tr><td><strong>lower(e)</strong> / <strong>floor(e)</strong></td><td>Greatest element &lt; e / &le; e</td><td>O(log n)</td></tr>\n<tr><td><strong>higher(e)</strong> / <strong>ceiling(e)</strong></td><td>Smallest element &gt; e / &ge; e</td><td>O(log n)</td></tr>\n<tr><td><strong>headSet(to)</strong> / <strong>tailSet(from)</strong> / <strong>subSet(a, b)</strong></td><td>Range views</td><td>O(log n)</td></tr>\n<tr><td><strong>descendingSet()</strong> / <strong>descendingIterator()</strong></td><td>Reverse order view / iterator</td><td>O(1)</td></tr>\n<tr><td><strong>iterator()</strong> / <strong>forEach(a)</strong> / <strong>stream()</strong></td><td>Walk in sorted order</td><td>O(n)</td></tr>\n<tr><td><strong>comparator()</strong></td><td>The Comparator in use (null for natural order)</td><td>O(1)</td></tr>\n<tr><td><strong>clone()</strong> / <strong>equals</strong> / <strong>toString</strong></td><td>Copy and compare</td><td>O(n)</td></tr>\n<tr><td><strong>reversed()</strong> / <strong>getFirst()</strong> / <strong>getLast()</strong></td><td>Java 21 sequenced methods</td><td>O(1) / O(log n)</td></tr>\n</table>"
